/* From Uiverse.io by fabiodevbr - Tags: button, click, animated, copy, click effect */
.__UIV_SCOPE__ button {
  background-color: #F2F7FA;
  width: 100px;
  height: 30px;
  border: none;
  border-radius: 10px;
  font-weight: 600;
  overflow: hidden;
  transition-duration: 700ms;
}

.__UIV_SCOPE__ button span:first-child {
  color: #0E418F;
  position: absolute;
  transform: translate(-50%, -50%)
}

.__UIV_SCOPE__ button span:last-child {
  position: absolute;
  color: #B5CCF3;
  opacity: 0;
  transform: translateY(100%) translateX(-50%);
  height: 14px;
  line-height: 13px;
}

.__UIV_SCOPE__ button:focus {
  background-color: #0E418F;
  width: 120px;
  height: 40px;
  transition-delay: 100ms;
  transition-duration: 500ms;
}

.__UIV_SCOPE__ button:focus span:first-child {
  color: #B5CCF3;
  transform: translateX(-50%) translateY(-150%);
  opacity: 0;
  transition-duration: 500ms;
}

.__UIV_SCOPE__ button:focus span:last-child {
  transform: translateX(-50%) translateY(-50%);
  opacity: 1;
  transition-delay: 300ms;
  transition-duration: 500ms;
}

.__UIV_SCOPE__ button:focus:end {
  background-color: #FFFFFF;
  width: 120px;
  height: 40px;
  transition-duration: 900ms;
}

.__UIV_SCOPE__ .centralize {
  width: 100%;
  height: 100%;
  display: flex;
  justify-content: center;
  align-items: center;
  text-align: center;
}

.__UIV_SCOPE__ .description {
  margin-top: 10px;
  color: #B5CCF3;
}
